import{_ as a,c as n,o as l,a3 as e}from"./chunks/framework.MI-M1z4O.js";const p=JSON.parse('{"title":"スクランバン（Scrumban）","description":"スクランバン（Scrumban）は、スクラムの反復的な構造とカンバンのフロー管理・WIP制限を組み合わせ、柔軟かつ効率的に作業を管理するハイブリッド型アジャイル手法です。","frontmatter":{"title":"スクランバン（Scrumban）","description":"スクランバン（Scrumban）は、スクラムの反復的な構造とカンバンのフロー管理・WIP制限を組み合わせ、柔軟かつ効率的に作業を管理するハイブリッド型アジャイル手法です。","head":[["meta",{"name":"keywords","content":"スクランバン, Scrumban, スクランバン紹介, スクランバン概要, スクランバンとは, Scrumban紹介, Scrumban概要, スクラムとカンバンの違い, スクラム vs カンバン, アジャイル手法, アジャイルフレームワーク, カンバン手法, スクラム手法, スクランバンプロセス, スクランバン運用ガイド, スクランバンボード, WIP制限, ワークフロー管理, カンバンボードの使い方, スクランバンのメリット, スクランバンの特徴, スクランバンの効果, スクランバン活用事例, スクランバン導入効果, スクランバン Jira設定, スクランバンボードテンプレート, Scrumbanツール, スクランバンコラボレーションツール, スクランバンワークフロー, アジャイルプロジェクト管理, 業務効率化手法, 反復的タスク管理, ボトルネック解消"}],["meta",{"property":"og:title","content":"スクランバン"}],["meta",{"property":"og:description","content":"スクランバン（Scrumban）は、スクラムの反復的な構造とカンバンのフロー管理・WIP制限を組み合わせ、柔軟かつ効率的に作業を管理するハイブリッド型アジャイル手法です。"}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/ja/agile/scrumban"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/ja/agile/scrumban"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/agile/scrumban"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/agile/scrumban"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/agile/scrumban"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/agile/scrumban"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"Empasy Docs"}],["meta",{"property":"og:title","content":"スクランバン（Scrumban） | Empasy Docs"}],["meta",{"property":"og:description","content":"スクランバン（Scrumban）は、スクラムの反復的な構造とカンバンのフロー管理・WIP制限を組み合わせ、柔軟かつ効率的に作業を管理するハイブリッド型アジャイル手法です。"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/ja/agile/scrumban"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"スクランバン（Scrumban） | Empasy Docs"}],["meta",{"name":"twitter:description","content":"スクランバン（Scrumban）は、スクラムの反復的な構造とカンバンのフロー管理・WIP制限を組み合わせ、柔軟かつ効率的に作業を管理するハイブリッド型アジャイル手法です。"}]],"sort":201},"headers":[],"relativePath":"ja/agile/scrumban.md","filePath":"ja/agile/scrumban.md","lastUpdated":1795293539000}'),i={name:"ja/agile/scrumban.md"};function r(s,t,o,g,d,h){return l(),n("div",null,[...t[0]||(t[0]=[e(`<h1 id="スクランバン-scrumban" tabindex="-1">スクランバン（Scrumban） <a class="header-anchor" href="#スクランバン-scrumban" aria-label="Permalink to “スクランバン（Scrumban）”">​</a></h1><blockquote><p><strong>一言まとめ:</strong> スクランバンは、スクラムの構造（役割／ミーティング／バックログの概念）とカンバンのフロー重視・WIP制限（Work In Progress制限）を組み合わせたプロセスです。スプリントの厳格さではなく <strong>フロー（Flow）</strong> と <strong>プル（Pull）</strong> を重視しつつ、必要な箇所にはスクラム式のイベント（計画・振り返り）を維持します。</p></blockquote><blockquote><p><strong>ご案内:</strong> 事業全周期の受注、契約、125種の単一標準成果物の納品およびAI開発ライフサイクル（AI-SDLC）については、<strong><a href="/ja/methodology/">エムパシー事業・開発メソドロジー総合ポータル</a></strong>をご参照ください。</p></blockquote><h2 id="概要・定義" tabindex="-1">概要・定義 <a class="header-anchor" href="#概要・定義" aria-label="Permalink to “概要・定義”">​</a></h2><p><strong>スクランバン（Scrumban）</strong> は、ソフトウェア開発および知識労働チームが柔軟にワークフローを管理できるように設計されたハイブリッド型プロセスです。</p><ul><li><strong>スクラム</strong>: 反復（スプリント）、固定されたイベント（スプリントプランニング・レビュー・レトロスペクティブ）、明確な役割</li><li><strong>カンバン</strong>: 視覚的なボード、WIP制限、プルベースの作業、継続的改善 スクランバンは上記2つのアプローチの利点を取り入れながら、<strong>現実的なフローの改善</strong>に焦点を当てます。</li></ul><h2 id="どのような場合にスクランバンを使うべきか" tabindex="-1">どのような場合にスクランバンを使うべきか？ <a class="header-anchor" href="#どのような場合にスクランバンを使うべきか" aria-label="Permalink to “どのような場合にスクランバンを使うべきか？”">​</a></h2><ul><li>従来 <strong>スクラム</strong> を使用しているが、頻繁な変更（緊急リクエスト）が多く、スプリント単位でまとめるのが難しい場合。</li><li><strong>カンバン</strong> でフローを回しているものの、バックログ管理・優先順位付け・定期的な振り返りといった規律が必要なチーム。</li><li>保守・運用・サポート（運用タスクと新機能開発が混在する）チーム。</li><li>予測よりも <strong>継続的デリバリー（Continuous Delivery）</strong> とフローの最適化をより重視する場合。</li></ul><h2 id="コアコンセプト" tabindex="-1">コアコンセプト <a class="header-anchor" href="#コアコンセプト" aria-label="Permalink to “コアコンセプト”">​</a></h2><ol><li><strong>Pullシステム</strong>: 作業はチームが処理可能なタイミングでのみ開始します（次の列へ引き込む）。</li><li><strong>WIP（進行中の作業）制限</strong>: 同時に進行する作業数を制限し、マルチタスクを減らして完了を促進します。</li><li><strong>視覚化されたボード</strong>: 作業のステータスを明確に示し、ボトルネックを即座に確認できます。</li><li><strong>定期的なリフィル（Replenishment）／プランニング</strong>: 必要なタイミングでのみバックログから作業を補充します（定期的、またはしきい値到達時）。</li><li><strong>測定と改善</strong>: サイクルタイム、リードタイム、スループットなどの指標を用いてフローを改善します。</li><li><strong>明示的なポリシー（Explicit Policies）</strong>: 列の移行条件、優先順位ルール、Definition of Ready/Doneを明文化します。</li></ol><h2 id="スクラム-vs-カンバン-vs-スクランバン" tabindex="-1">スクラム vs カンバン vs スクランバン <a class="header-anchor" href="#スクラム-vs-カンバン-vs-スクランバン" aria-label="Permalink to “スクラム vs カンバン vs スクランバン”">​</a></h2><table tabindex="0"><thead><tr><th>項目</th><th style="text-align:right;">スクラム</th><th>カンバン</th><th>スクランバン</th></tr></thead><tbody><tr><td>反復（スプリント）</td><td style="text-align:right;">あり（固定長）</td><td>なし（継続的フロー）</td><td>選択的／短いイテレーションの併用</td></tr><tr><td>WIP制限</td><td style="text-align:right;">暗黙的（スプリント範囲）</td><td>明示的</td><td>明示的（中核）</td></tr><tr><td>計画方式</td><td style="text-align:right;">スプリントプランニング</td><td>リフィル／プルベース</td><td>リフィル ＋ 必要に応じたプランニング</td></tr><tr><td>役割</td><td style="text-align:right;">PO/SM/Dev</td><td>柔軟（役割なし）</td><td>PO ＋ Flow Manager（またはSMの役割を維持）</td></tr><tr><td>目標</td><td style="text-align:right;">コミット（スプリント目標）</td><td>フロー最適化</td><td>フロー最適化 ＋ 優先順位管理</td></tr></tbody></table><h2 id="役割と責任" tabindex="-1">役割と責任 <a class="header-anchor" href="#役割と責任" aria-label="Permalink to “役割と責任”">​</a></h2><ul><li><strong>Product Owner（PO）</strong>: バックログの優先順位付け、ステークホルダーとの調整、ビジネス価値の定義</li><li><strong>Flow Manager（またはScrum Masterの役割を維持）</strong>: フローのモニタリング、ボトルネック解消の支援、プロセス改善の促進</li><li><strong>チーム（開発者／テスターなど）</strong>: 定義されたポリシーの遵守、WIP上限内でのプル方式による作業の開始／完了</li><li><strong>Stakeholders</strong>: 要件・フィードバックの提供、レビューへの参加（必要時）</li></ul><blockquote><p>役割はチームの状況に合わせて柔軟に調整してください。重要なのは <strong>フロー管理の責任</strong> が明確であることです。</p></blockquote><h2 id="主要アーティファクト・ツール" tabindex="-1">主要アーティファクト・ツール <a class="header-anchor" href="#主要アーティファクト・ツール" aria-label="Permalink to “主要アーティファクト・ツール”">​</a></h2><ul><li><strong>カンバンボード</strong>（物理またはデジタル）— 列とWIP上限を含む</li><li><strong>バックログ（優先順位付きリスト）</strong> — プル待ち状態の作業候補</li><li><strong>明示的なポリシー（Explicit policies）</strong> — 列の移行ルール、定義（Ready/Done）</li><li><strong>サービスクラス（Classes of Service）</strong> — 緊急／固定日／標準などの優先度タイプ</li><li><strong>メトリクスダッシュボード</strong>: サイクルタイム、リードタイム、スループット、CFD（累積フロー図）</li></ul><h2 id="ボードレイアウト" tabindex="-1">ボードレイアウト <a class="header-anchor" href="#ボードレイアウト" aria-label="Permalink to “ボードレイアウト”">​</a></h2><p>基本的なスクランバンボード（例）：</p><table tabindex="0"><thead><tr><th>列</th><th>説明</th><th style="text-align:right;">推奨WIP上限</th></tr></thead><tbody><tr><td>Backlog</td><td>優先順位が付けられたすべての作業</td><td style="text-align:right;">—</td></tr><tr><td>Ready</td><td>開始可能な作業（Doingへ移動可能な状態）</td><td style="text-align:right;">—</td></tr><tr><td>Doing / In Progress</td><td>実際に作業中</td><td style="text-align:right;">3</td></tr><tr><td>Code Review</td><td>レビュー待ち</td><td style="text-align:right;">2</td></tr><tr><td>Testing</td><td>QA／検証</td><td style="text-align:right;">2</td></tr><tr><td>Done</td><td>完了</td><td style="text-align:right;">—</td></tr></tbody></table><p><strong>簡易ASCIIボード:</strong></p><div class="language-"><button title="コードをコピー" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Backlog -&gt; Ready -&gt; [Doing (WIP 3)] -&gt; Code Review (WIP 2) -&gt; Testing (WIP 2) -&gt; Done</span></span></code></pre></div><h2 id="ワークフロールールの例" tabindex="-1">ワークフロールールの例 <a class="header-anchor" href="#ワークフロールールの例" aria-label="Permalink to “ワークフロールールの例”">​</a></h2><div class="language-text"><button title="コードをコピー" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Policy: Pull条件（Doing列への移動）</span></span>
<span class="line"><span>- カードがReady列にあり、かつDoing列のWIP &lt; WIP上限</span></span>
<span class="line"><span>- 該当作業の「Definition of Ready」を満たしている（要件／テストケース／デザインなど）</span></span>
<span class="line"><span>- 必要なリソース（テスター／レビュアー）の稼働可否を確認済み</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Policy: Definition of Done（完了の定義）</span></span>
<span class="line"><span>- コードがマージされ、ビルドが成功している</span></span>
<span class="line"><span>- 自動／手動テストに合格している</span></span>
<span class="line"><span>- デプロイ（またはQA引き継ぎ）のドキュメント化が完了している</span></span></code></pre></div><p><strong>Classes of Serviceの例</strong></p><ul><li><strong>Expedite</strong>: 即時処理（作業優先度最上位、WIP例外を許容）</li><li><strong>Fixed Date</strong>: 特定の日付が必要 — スケジュール監視が必要</li><li><strong>Standard</strong>: 通常リクエスト</li><li><strong>Intangible</strong>: 技術的負債などの長期的価値</li></ul><h2 id="イベントと推奨周期" tabindex="-1">イベントと推奨周期 <a class="header-anchor" href="#イベントと推奨周期" aria-label="Permalink to “イベントと推奨周期”">​</a></h2><ul><li><strong>Daily Stand-up（毎日、10〜15分）</strong>: フロー中心で実施（何をしているかよりもボトルネック／ブロッカーの共有）</li><li><strong>Replenishment / Backlog Refinement（週1回または必要時）</strong>: Ready列の補充 — 優先順位の再整理</li><li><strong>Planning（必要時）</strong>: 大きな作業（エピック）の分割または代替計画 — 短時間で実施</li><li><strong>Retrospective（2〜4週間周期）</strong>: プロセス改善、WIP上限の調整検討</li><li><strong>Service Delivery Review / Ops Review（月次）</strong>: SLA・SLE・指標のレビュー</li></ul><blockquote><p>スクラムのようにすべての会議を厳格に固定する必要はありません。<strong>フローを妨げるポイント</strong> が見えたときに会議を導入してください。</p></blockquote><h2 id="見積り・計画方法" tabindex="-1">見積り・計画方法 <a class="header-anchor" href="#見積り・計画方法" aria-label="Permalink to “見積り・計画方法”">​</a></h2><ul><li><strong>ストーリーポイントの維持</strong>: スクラムから移行するチームに適しています。スループット対比の予測に有利です。</li><li><strong>No Estimates（見積り省略）</strong>: カードの単純カウント ＋ サイクルタイム／スループットによる予測。</li><li><strong>バケット（期間ベース）計画</strong>: 月ごとに完了可能な作業量（スループット）を基準にリフィルします。</li><li><strong>推奨</strong>: 重い見積り作業を減らし、<strong>実績データ（サイクルタイム、スループット）</strong> に基づいて予測してください。</li></ul><h2 id="主要メトリクス-定義・活用" tabindex="-1">主要メトリクス（定義・活用） <a class="header-anchor" href="#主要メトリクス-定義・活用" aria-label="Permalink to “主要メトリクス（定義・活用）”">​</a></h2><ul><li><strong>リードタイム（Lead Time）</strong> = カードがバックログ登録（または作成）された時点 → 完了時点</li><li><strong>サイクルタイム（Cycle Time）</strong> = 作業開始（Doing） → 完了</li><li><strong>スループット（Throughput）</strong> = 特定期間内に完了したカード数</li><li><strong>WIP（平均進行中作業数）</strong></li><li><strong>Cumulative Flow Diagram（CFD）</strong>: 各列の累積領域によりボトルネック・フローの変化を可視化</li><li><strong>サービスレベル期待値（SLE）</strong>: 例：85%の作業が10日以内に完了すること</li></ul><p><strong>参考活用法</strong></p><ul><li>Little’s Law: <code>WIP = Throughput × Cycle Time</code>（平均値を使用）— 予測および限界把握に有用</li><li>目標: サイクルタイムの安定化 → 予測可能性の向上</li></ul><h2 id="スクラムからスクランバンへの移行" tabindex="-1">スクラムからスクランバンへの移行 <a class="header-anchor" href="#スクラムからスクランバンへの移行" aria-label="Permalink to “スクラムからスクランバンへの移行”">​</a></h2><ol><li><strong>現在のプロセスのマッピング</strong>: どのような仕事がどのように流れているかを可視化</li><li><strong>ボードの構成</strong>: 最小限の列から開始（Ready → Doing → QA → Done）</li><li><strong>WIP上限の設定</strong>: 保守的に開始（例：Doing = チームメンバー数 ÷ 2）</li><li><strong>リフィルルールの策定</strong>: いつBacklogからReadyへ補充するかを決定（週次／しきい値）</li><li><strong>データ収集</strong>: サイクルタイム・スループットの収集（2〜4週間）</li><li><strong>調整の反復</strong>: レトロスペクティブでWIP・列・ポリシーを調整</li></ol><h2 id="カンバン-スクランバン導入チェックリスト" tabindex="-1">カンバン／スクランバン導入チェックリスト <a class="header-anchor" href="#カンバン-スクランバン導入チェックリスト" aria-label="Permalink to “カンバン／スクランバン導入チェックリスト”">​</a></h2><ul><li>[ ] ボードがチームの実態を反映しているか？</li><li>[ ] WIP上限が設定されており、全員が理解しているか？</li><li>[ ] Definition of Ready/Doneがドキュメント化されているか？</li><li>[ ] Replenishmentの周期（またはルール）が決まっているか？</li><li>[ ] Daily stand-upでボトルネック中心の議論が行われているか？</li><li>[ ] サイクルタイム・スループット・CFDを収集し分析しているか？</li><li>[ ] サービスクラスとポリシーが定義されているか？</li><li>[ ] 定期的なレトロスペクティブでプロセス変更が反映されているか？</li></ul><h2 id="実践のヒント-ベストプラクティス" tabindex="-1">実践のヒント＆ベストプラクティス <a class="header-anchor" href="#実践のヒント-ベストプラクティス" aria-label="Permalink to “実践のヒント＆ベストプラクティス”">​</a></h2><ul><li><strong>小さく始める</strong>: ボードとWIP上限を小さく作り、素早くフィードバックを得ます。</li><li><strong>Stop starting — start finishing</strong>: 新しい作業を始めることよりも、進行中の仕事を終わらせる文化を根付かせます。</li><li><strong>WIP違反時のチーム規律</strong>: 即座に議論します（なぜ違反したのか、ボトルネックの原因を把握）。</li><li><strong>視覚的シグナル</strong>: ブロッカー／緊急カードは別の色やステッカーで表示します。</li><li><strong>ポリシーはドキュメント化</strong>: 「いつカードを移動させるか」を明確に記述しておきます。</li><li><strong>自動化</strong>: CI/CD、自動テストによってサイクルタイムを短縮します。</li><li><strong>データに基づく意思決定</strong>: 見積りよりも実際のサイクルタイム／スループットで計画します。</li></ul><h2 id="よくある失敗" tabindex="-1">よくある失敗 <a class="header-anchor" href="#よくある失敗" aria-label="Permalink to “よくある失敗”">​</a></h2><ul><li>WIP上限を設定しただけで守らないケース</li><li>スクラムのイベントをそのまま維持しながらWIP・プルの概念を無視するケース</li><li>クラスを作成したものの基準なしに使用するケース（優先順位の混乱）</li><li>指標を収集せず「感覚」だけで意思決定するケース</li><li>列や細分化が多すぎてボードが複雑化するケース</li></ul><h2 id="テンプレート-replenishmentミーティング-簡易アジェンダ" tabindex="-1">テンプレート：Replenishmentミーティング（簡易アジェンダ） <a class="header-anchor" href="#テンプレート-replenishmentミーティング-簡易アジェンダ" aria-label="Permalink to “テンプレート：Replenishmentミーティング（簡易アジェンダ）”">​</a></h2><ol><li>先週完了した作業（簡易レビュー） — 5分</li><li>Ready列の状態確認（優先順位の再整列） — 10〜20分</li><li>WIP上限に対する現在の稼働リソース確認 — 5分</li><li>新規作業のPull決定（優先順位順に補充） — 10〜20分</li><li>Blocker／リスク要因の共有 — 5分</li></ol><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to “FAQ”">​</a></h2><p><strong>Q. スプリントは完全になくなりますか？</strong> A. チームが希望すれば、短いイテレーション（例：2週間）を維持しながらスクランバン原則を適用できます。重要なのはフローの改善です。</p><p><strong>Q. ストーリーポイントは使い続けるべきですか？</strong> A. 必ずしもそうする必要はありません。スループットとサイクルタイムで予測する方法も多く使われています。チーム文化や報告の必要性に応じて決定してください。</p><p><strong>Q. WIP上限はどのように決めますか？</strong> A. 保守的に始めます（チームメンバー数基準、または過去のスループットから推定）。上限を守りながら段階的に調整します。</p><h2 id="適用例" tabindex="-1">適用例 <a class="header-anchor" href="#適用例" aria-label="Permalink to “適用例”">​</a></h2><ul><li>チームメンバー5名 → Doing WIP = 3（同時作業制限）</li><li>Replenishment：週1回（月曜日）</li><li>Retrospective：2週間ごと（オンライン・オフライン併用）</li><li>指標：週単位のスループット ＋ 4週間の累積サイクルタイムの観察</li></ul><h2 id="まとめ-—-導入ガイド" tabindex="-1">まとめ — 導入ガイド <a class="header-anchor" href="#まとめ-—-導入ガイド" aria-label="Permalink to “まとめ — 導入ガイド”">​</a></h2><ol><li><strong>ボードを作成し</strong>、</li><li><strong>WIP上限を定め</strong>、</li><li><strong>プル（Pull）ルールとDefinitionをドキュメント化</strong> したうえで、</li><li><strong>データ（サイクルタイム・スループット）を2〜4週間収集</strong> し、<strong>レトロスペクティブで調整</strong> してください。</li></ol>`,53)])])}const m=a(i,[["render",r]]);export{p as __pageData,m as default};
